import pandas as pd
import matplotlib.pyplot as plt
import base64
from io import BytesIO
import re
from collections import Counter
import json

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# Calculate KPIs
total_questions = len(df)
years = df['year'].nunique()
year_min = df['year'].min()
year_max = df['year'].max()

type_counts = df['type'].value_counts()
mcq_count = type_counts.get('MCQs', 0)
short_count = type_counts.get('Short', 0)
long_count = type_counts.get('Long', 0)

avg_questions_per_year = total_questions / years

# Yearly trends
yearly_counts = df.groupby('year').size()
yearly_type_counts = df.groupby(['year', 'type']).size().unstack(fill_value=0)

# YoY Change
yoy_change = yearly_counts.diff()
yoy_pct_change = yearly_counts.pct_change() * 100

# Text analysis (Keywords)
def get_keywords(text):
    text = str(text).lower()
    text = re.sub(r'[\$\(\)\[\]\{\}\"\'\,\.\:\;\?\!\\/]', ' ', text)
    words = text.split()
    # Exclude common stop words and generic exam terms
    stopwords = {'the', 'is', 'a', 'of', 'and', 'in', 'to', 'what', 'are', 'write', 'define', 'explain', 
                 'which', 'for', 'with', 'this', 'an', 'used', 'from', 'called', 'by', 'be', 'it', 'can', 
                 'do', 'how', 'any', 'or', 'on', 'program', 'example', 'statement', 'following', 'output', 
                 'given', 'between', 'different', 'where', 'also', 'has', 'not', 'that', 'its', 'all', 'into', 'when'}
    return [w for w in words if w not in stopwords and len(w) > 2 and not w.isdigit()]

all_words = []
df['question'].apply(lambda x: all_words.extend(get_keywords(x)))
word_counts = Counter(all_words).most_common(25)

# Generates Charts
# 1. Total Questions by Year
fig1, ax1 = plt.subplots(figsize=(10, 5))
yearly_counts.plot(kind='line', marker='o', ax=ax1, color='#2563eb', linewidth=2)
ax1.set_title('Total Questions per Year (2015-2025)')
ax1.set_xlabel('Year')
ax1.set_ylabel('Number of Questions')
ax1.grid(True, linestyle='--', alpha=0.7)
ax1.set_xticks(range(year_min, year_max + 1))
img_yearly = fig_to_base64(fig1)

# 2. Question Types Distribution (Overall)
fig2, ax2 = plt.subplots(figsize=(6, 6))
type_counts.plot(kind='pie', autopct='%1.1f%%', ax=ax2, colors=['#3b82f6', '#10b981', '#f59e0b'], startangle=90)
ax2.set_title('Overall Question Type Distribution')
ax2.set_ylabel('')
img_types = fig_to_base64(fig2)

# 3. Question Types by Year
fig3, ax3 = plt.subplots(figsize=(10, 6))
yearly_type_counts.reindex(columns=['MCQs', 'Short', 'Long']).plot(kind='bar', stacked=True, ax=ax3, color=['#3b82f6', '#10b981', '#f59e0b'])
ax3.set_title('Question Types Breakdown per Year')
ax3.set_xlabel('Year')
ax3.set_ylabel('Number of Questions')
ax3.legend(title='Question Type')
img_types_yearly = fig_to_base64(fig3)

# 4. Top Keywords
fig4, ax4 = plt.subplots(figsize=(12, 6))
pd.DataFrame(word_counts, columns=['Keyword', 'Count']).set_index('Keyword').plot(kind='bar', ax=ax4, color='#8b5cf6', legend=False)
ax4.set_title('Top 25 Most Frequent Keywords/Topics in Questions')
ax4.set_xlabel('Keyword')
ax4.set_ylabel('Frequency')
ax4.tick_params(axis='x', rotation=45)
plt.tight_layout()
img_keywords = fig_to_base64(fig4)

# Dynamic HTML Generation
